import{_ as l,o as a,c as i,ae as o}from"./chunks/framework.RRduUuAx.js";const g=JSON.parse('{"title":"貔貅账单导入指南","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh/guide/07-pixiu-bill-import-guide.md","filePath":"v1/zh/guide/07-pixiu-bill-import-guide.md"}'),r={name:"v1/zh/guide/07-pixiu-bill-import-guide.md"};function e(d,t,n,h,s,c){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="貔貅账单导入指南" tabindex="-1">貔貅账单导入指南 <a class="header-anchor" href="#貔貅账单导入指南" aria-label="Permalink to &quot;貔貅账单导入指南&quot;">​</a></h1><h2 id="📋-概述" tabindex="-1">📋 概述 <a class="header-anchor" href="#📋-概述" aria-label="Permalink to &quot;📋 概述&quot;">​</a></h2><p>本指南将指导您如何从 <strong>貔貅记账</strong> 导出账单，并导入到 <strong>考拉记账</strong> App 中。</p><p>考拉记账当前支持导入 <strong>貔貅记账导出的 CSV 账单文件</strong>（仅 CSV）。</p><hr><h2 id="📱-第一步-在貔貅记账中导出账单" tabindex="-1">📱 第一步：在貔貅记账中导出账单 <a class="header-anchor" href="#📱-第一步-在貔貅记账中导出账单" aria-label="Permalink to &quot;📱 第一步：在貔貅记账中导出账单&quot;">​</a></h2><p>不同版本的貔貅记账，入口可能略有差异，但思路一致：进入“数据导出/导出账单”，选择时间范围与导出格式后保存文件。</p><h3 id="步骤-1-进入导出入口" tabindex="-1">步骤 1：进入导出入口 <a class="header-anchor" href="#步骤-1-进入导出入口" aria-label="Permalink to &quot;步骤 1：进入导出入口&quot;">​</a></h3><ol><li>打开 <strong>貔貅记账</strong> App</li><li>进入 <strong>我的</strong></li><li>找到 <strong>数据导出 / 导出账单</strong>（名称可能略有不同）</li></ol><h3 id="步骤-2-选择导出时间范围" tabindex="-1">步骤 2：选择导出时间范围 <a class="header-anchor" href="#步骤-2-选择导出时间范围" aria-label="Permalink to &quot;步骤 2：选择导出时间范围&quot;">​</a></h3><ol><li>选择要导出的时间范围（如：最近一个月、最近三个月）</li><li>确认范围后开始导出</li></ol><blockquote><p>💡 <strong>提示</strong>：</p><ul><li>建议一次导出不超过 3 个月，避免文件过大导致解析变慢</li><li>数据量很大时，可以分多次导出后分批导入</li></ul></blockquote><h3 id="步骤-3-选择导出格式并保存文件" tabindex="-1">步骤 3：选择导出格式并保存文件 <a class="header-anchor" href="#步骤-3-选择导出格式并保存文件" aria-label="Permalink to &quot;步骤 3：选择导出格式并保存文件&quot;">​</a></h3><ol><li>选择导出格式：<strong>CSV</strong></li><li>将导出的 CSV 文件保存到设备本地（或通过“分享/保存到文件”）</li><li>记住文件保存位置，便于后续导入</li></ol><hr><h2 id="📱-第二步-在考拉记账中导入" tabindex="-1">📱 第二步：在考拉记账中导入 <a class="header-anchor" href="#📱-第二步-在考拉记账中导入" aria-label="Permalink to &quot;📱 第二步：在考拉记账中导入&quot;">​</a></h2><h3 id="步骤-1-进入导入页面" tabindex="-1">步骤 1：进入导入页面 <a class="header-anchor" href="#步骤-1-进入导入页面" aria-label="Permalink to &quot;步骤 1：进入导入页面&quot;">​</a></h3><ol><li>打开考拉记账 App</li><li>点击底部导航栏的 <strong>“设置”</strong></li><li>在设置页面中找到 <strong>“账单导入”</strong></li><li>点击进入账单导入页面</li></ol><h3 id="步骤-2-选择导入来源" tabindex="-1">步骤 2：选择导入来源 <a class="header-anchor" href="#步骤-2-选择导入来源" aria-label="Permalink to &quot;步骤 2：选择导入来源&quot;">​</a></h3><ol><li>点击 <strong>“导入来源”</strong></li><li>在列表中选择 <strong>“貔貅记账”</strong></li></ol><blockquote><p>⚠️ <strong>重要</strong>：必须选择“貔貅记账”，否则可能导致文件格式校验失败或字段解析错误。</p></blockquote><h3 id="步骤-3-选择文件" tabindex="-1">步骤 3：选择文件 <a class="header-anchor" href="#步骤-3-选择文件" aria-label="Permalink to &quot;步骤 3：选择文件&quot;">​</a></h3><ol><li>点击 <strong>“文件路径”</strong></li><li>选择从貔貅记账导出的 <strong>CSV</strong> 文件</li><li>确认文件名已显示</li></ol><h3 id="步骤-4-关联账本" tabindex="-1">步骤 4：关联账本 <a class="header-anchor" href="#步骤-4-关联账本" aria-label="Permalink to &quot;步骤 4：关联账本&quot;">​</a></h3><ol><li>点击 <strong>“关联账本”</strong></li><li>选择要导入的目标账本</li><li>确认账本选择</li></ol><h3 id="步骤-5-解析并预览" tabindex="-1">步骤 5：解析并预览 <a class="header-anchor" href="#步骤-5-解析并预览" aria-label="Permalink to &quot;步骤 5：解析并预览&quot;">​</a></h3><ol><li>点击右上角 <strong>“解析”</strong></li><li>解析成功后进入预览页</li><li>预览页可对单条记录进行编辑/删除，也可以批量跳过无效记录</li></ol><h3 id="步骤-6-导入" tabindex="-1">步骤 6：导入 <a class="header-anchor" href="#步骤-6-导入" aria-label="Permalink to &quot;步骤 6：导入&quot;">​</a></h3><ol><li>预览确认无误后点击 <strong>“导入”</strong></li><li>等待导入完成</li></ol><hr><h2 id="📋-貔貅账单文件格式说明-csv" tabindex="-1">📋 貔貅账单文件格式说明（CSV） <a class="header-anchor" href="#📋-貔貅账单文件格式说明-csv" aria-label="Permalink to &quot;📋 貔貅账单文件格式说明（CSV）&quot;">​</a></h2><p>考拉记账对貔貅账单 CSV 的校验点：</p><ul><li>第一行必须是表头</li><li><strong>表头列数必须为 10 列</strong></li><li>内容使用英文逗号 <code>,</code> 作为分隔符（CSV 标准）</li></ul><h3 id="列定义-按顺序" tabindex="-1">列定义（按顺序） <a class="header-anchor" href="#列定义-按顺序" aria-label="Permalink to &quot;列定义（按顺序）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>列序号</th><th>列含义</th><th>说明</th></tr></thead><tbody><tr><td>1</td><td>日期</td><td>支持 <code>yyyy-MM-dd</code> / <code>yyyy/MM/dd</code>，且年份需 ≥ 2016；否则视为无效日期</td></tr><tr><td>2</td><td>父分类</td><td>用于匹配考拉记账的收支项目父类名称</td></tr><tr><td>3</td><td>交易分类</td><td>文本需包含“支出”或“收入”关键字；包含“收入”则按收入导入，否则按支出导入</td></tr><tr><td>4</td><td>子分类</td><td>用于匹配考拉记账的收支项目子类名称</td></tr><tr><td>5</td><td>流入金额</td><td>收入金额列（允许带 <code>-</code>，导入会自动去除符号）</td></tr><tr><td>6</td><td>流出金额</td><td>支出金额列（允许带 <code>-</code>，导入会自动去除符号）</td></tr><tr><td>7</td><td>币种代码</td><td>例如 <code>CNY</code> / <code>USD</code>；为空时使用目标账本的默认币种</td></tr><tr><td>8</td><td>账户</td><td>账户名称（用于匹配考拉记账账户；不存在时导入阶段会尝试创建）</td></tr><tr><td>9</td><td>标签</td><td>多个标签用逗号分隔（同时支持中文逗号 <code>，</code>）</td></tr><tr><td>10</td><td>备注</td><td>备注文本</td></tr></tbody></table><h3 id="导入映射-考拉记账" tabindex="-1">导入映射（考拉记账） <a class="header-anchor" href="#导入映射-考拉记账" aria-label="Permalink to &quot;导入映射（考拉记账）&quot;">​</a></h3><ul><li>日期 → 账单日期</li><li>交易分类（含支出/收入关键字）→ 账单类型</li><li>父分类 + 子分类 → 收支项目（匹配不到会被标记为不完善数据）</li><li>流入/流出金额 → 金额（由账单类型决定取哪一列）</li><li>账户 → 账户（按名称匹配；不存在会在导入时创建）</li><li>标签 → 标签（按名称匹配/创建并绑定到记录）</li><li>备注 → 备注</li><li>币种代码 → 账单货币（按 code 匹配；匹配失败使用账本默认币种）</li><li>c</li><li>日期（row[0]）→ 账单日期</li><li>父类（row[1]）→ 一级分类 （并匹配/创建 parentCategoryId 等）</li><li>交易分类（row[2]，含“收入/支出”）→ 账单类型（收入/支出）</li><li>子类（row[3]）→ 二级分类 （并匹配/创建 childCategoryId 等）</li><li>流入金额（row[4]）/流出金额（row[5]）→ 账单金额 （按 type 取其一）</li><li>货币代码（row[6]）→ 货币单位 （按 code 查）</li><li>账户（row[7]）→ 账户名称（按名称查找/创建）</li><li>标签（row[8]）→ 标签（解析/创建标签后入库）</li><li>备注（row[9]）→ 备注</li></ul><hr><h2 id="⚠️-注意事项" tabindex="-1">⚠️ 注意事项 <a class="header-anchor" href="#⚠️-注意事项" aria-label="Permalink to &quot;⚠️ 注意事项&quot;">​</a></h2><ol><li><strong>不自动去重</strong>：重复导入同一份文件会生成重复账单记录，请避免多次导入同一时间段。</li><li><strong>收支项目匹配</strong>：按“父分类 + 子分类”名称匹配；若匹配失败，预览页会提示不完善，需要手动选择正确的收支项目后再导入。</li><li><strong>账户有效性</strong>：账户名称为空或仅包含符号时，会被视为无效数据并提示补全。</li><li><strong>文件编码</strong>：CSV 支持 UTF-8/GBK；若出现乱码，建议用 UTF-8 重新导出或转换编码后再导入。</li></ol><hr><h2 id="🔧-常见问题" tabindex="-1">🔧 常见问题 <a class="header-anchor" href="#🔧-常见问题" aria-label="Permalink to &quot;🔧 常见问题&quot;">​</a></h2><h3 id="q1-提示-表头长度不对" tabindex="-1">Q1：提示“表头长度不对”？ <a class="header-anchor" href="#q1-提示-表头长度不对" aria-label="Permalink to &quot;Q1：提示“表头长度不对”？&quot;">​</a></h3><p><strong>A：</strong> 请确认导出的 CSV 第一行表头为 <strong>10 列</strong>。常见原因：</p><ol><li>使用了非貔貅记账导出的 CSV，列数不一致</li><li>用 Excel/WPS 二次编辑后出现多余分隔符导致列数变化</li><li>另存为 CSV 时选择了不兼容格式（例如带分号分隔）</li></ol><h3 id="q2-导入后金额不对或为-0" tabindex="-1">Q2：导入后金额不对或为 0？ <a class="header-anchor" href="#q2-导入后金额不对或为-0" aria-label="Permalink to &quot;Q2：导入后金额不对或为 0？&quot;">​</a></h3><p><strong>A：</strong> 请确认：</p><ol><li>“交易分类”列包含“支出/收入”关键字（决定取“流入金额”还是“流出金额”）</li><li>对应金额列有值且为数字格式（带 <code>-</code> 也可以，会自动去掉）</li></ol><h3 id="q3-分类匹配不上怎么办" tabindex="-1">Q3：分类匹配不上怎么办？ <a class="header-anchor" href="#q3-分类匹配不上怎么办" aria-label="Permalink to &quot;Q3：分类匹配不上怎么办？&quot;">​</a></h3><p><strong>A：</strong> 在导入预览页点进单条记录手动选择收支项目；或者先在考拉记账里创建好与貔貅导出文件同名的收支项目后再重新解析。</p><hr><p><strong>最后更新</strong>：2026年5月</p>',52)])])}const b=l(r,[["render",e]]);export{g as __pageData,b as default};
